 case 0:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">Start with the evidence.</h2><p>Every source stays dated. Current financials never enter the historical experiments.</p></div><label for="g-cutoff">Valuation date · UTC</label><input id="g-cutoff" type="date" value="${esc(draft.cutoff)}">${sourceEvidence()}<div class="model-boundary"><b>Model boundaries</b><p>Simplified nominal operating-company FCFF. Replacement capex, capital lead times, NOLs, financing, R&D/lease restatements and equity-award valuation are not separately modeled.</p></div>${(raw.reviewRequired||[]).length?`<details><summary>Unresolved source questions · ${raw.reviewRequired.length}</summary><ul>${raw.reviewRequired.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}`;
 case 1:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What makes this business work?</h2><p>A useful model begins with a testable story.</p></div>${note('today','Who pays, and for what?','Customers, products, segments, pricing and the economic engine…')}${note('change','What changes, and why?','Growth drivers, competitive advantage and the next evidence to watch…')}${note('break','What could break the story?','Name one or two falsifiable milestones.') }<details><summary>Normalize starting operating profit</summary><p class="micro">A net EBIT adjustment is not a substitute for coherent R&D, lease, reinvestment or stock-compensation restatement.</p><label for="g-normalize">Net EBIT adjustment · ${esc(snapshot.currency)} millions</label><input id="g-normalize" type="number" inputmode="decimal" ${precisionInputAttributes(draft.normalizationDelta)} step="1">${researchRationale('normalizationDelta')}${historyPanel('normalizationDelta')}<label for="g-adjust-reason">Economic reason</label><textarea id="g-adjust-reason">${esc(draft.adjustmentReason)}</textarea><label for="g-adjust-source">Supporting source URL</label><input id="g-adjust-source" type="url" value="${esc(draft.adjustmentSource)}"><p class="micro">A nonzero adjustment requires both a reason and a source.</p></details>`;
 case 2:return `<div class="editor-intro"><span class="eyebrow">YOUR ASSUMPTIONS</span><h2 id="guided-step-title" tabindex="-1">Build a growth story.</h2><p>Start with the company's track record. Make your own forward-looking case.</p></div>${growthPathControls()}${isFlexible()&&draft.operatingProfile.mode==='annual'?'':field('growth','Year 1 revenue growth',draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Year 1 of the staged capacity profile; later growth follows documented weights toward the stable rate.':isFlexible()?`Year 1 of your revenue-growth path, reaching stable growth in year ${draft.assumptions.years}. ${draft.operatingProfile.mode==='maintain'?'Held through the explicit phase, then fades to stable growth.':draft.operatingProfile.mode==='annual'?'The final explicit rate then fades to stable growth.':'Fades to stable growth at maturity.'}`:'Fades toward stable growth over a ten-year forecast.',100,'%',-30,100,.5)}<div id="approved-growth-path" class="approved-growth-path"></div><details id="approved-growth-explanations" class="approved-secondary-controls"><summary>Growth timing, method & evidence</summary></details><details class="approved-diagnostics"><summary>Revenue scale & capital implications</summary><div id="growth-scale" class="economic-insight"></div></details>${note('growth','Explain your growth story','Customers × spending, price versus volume, capacity and market share…')}`;
 case 3:return `<div class="editor-intro"><span class="eyebrow">YOUR ASSUMPTIONS</span><h2 id="guided-step-title" tabindex="-1">Turn revenue into profit.</h2><p>Operating margin and cash taxes determine earnings before reinvestment.</p></div>${field('targetMargin','Mature operating margin',draft.marginPath?.enabled?'Terminal EBIT margin reached in the independent terminal-margin year; the interim path can peak above it.':draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'GAAP EBIT margin reached in year 6 through the staged operating profile. The same progression applies in every simulation.':isFlexible()?`EBIT ÷ revenue, not gross or EBITDA margin. Converges from the normalized starting margin by year ${growthTimings().marginMaturityYears}, then stays at this target.`:'EBIT ÷ revenue, not gross or EBITDA margin. Fades from the normalized starting margin.',100,'%',0,70,.5)}${guidedMarginControls()}${timingInputs('margin')}${field('tax','Cash tax rate','Applied only to positive EBIT. No automatic tax credit on losses or NOL ledger.',100,'%',0,60,.5)}<div id="guided-margin-chart"></div><div id="approved-profit-chart" class="approved-profit-chart"></div><details id="approved-profit-explanations" class="approved-secondary-controls"><summary>Margin, tax controls & evidence</summary></details>${note('profit','Explain margins & taxes')}`;
 case 4:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What will growth cost?</h2><p>Growth creates value only when it earns enough on the capital it consumes.</p></div>${field('salesCapital',draft.capitalPath?.enabled?'Early incremental sales / capital':draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'||isFlexible()?'Initial incremental sales / capital':'Incremental sales / capital',draft.capitalPath?.enabled?'Extra annual revenue per unit of net new capital during the early phase. Set the later efficiency and independent phase dates below.':draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?'Initial productivity doubles by years 6–7, then capital intensity fades to match terminal margin, tax, growth and ROIC. Higher initial productivity reduces buildout investment.':isFlexible()?`Initial extra revenue per dollar of new invested capital. The separate capital-efficiency timing below determines when this changes. See Details for every annual value.`:'Extra annual revenue per dollar of new invested capital. Higher means less reinvestment.',1,'×',.1,15,.1)}${guidedCapitalControls()}${timingInputs('capital')}<div class="economic-insight">${draft.capitalPath?.enabled||draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'||isFlexible()?'Initially, each':'Each'} $1 of extra sales requires <b id="capital-per-dollar">${num(1/draft.assumptions.salesCapital,2)}</b> of new capital.</div><section id="guided-capital-diagnostics" aria-label="Live capital-efficiency diagnostics"></section><details><summary>Where this simplification can fail</summary><p>Maintenance replacement, asset lives, construction lead times and financing are not modeled separately. Declining revenue does not automatically release capital.</p></details>${note('investment','Explain capacity & capital needs')}`;
 case 5:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What does the long run look like?</h2><p>Keep risk, currency and the economics of mature growth consistent.</p></div>${field('wacc','Cost of capital · WACC','Nominal discount rate in the cash-flow currency. Constant in all forecast and terminal years; no risk or capital-structure fade. An assumption, not a live market estimate.',100,'%',1,30,.25)}${worksheet()}${field('terminalGrowth','Stable growth','Must remain below WACC and mature marginal ROIC.',100,'%',0,5,.25)}${field('terminalROIC','Mature marginal ROIC','Return on new capital in maturity. Historical average returns are only context.',100,'%',1,50,.5)}<div class="economic-insight">Stable growth reinvests <b id="stable-reinvestment">${pc(draft.assumptions.terminalGrowth/draft.assumptions.terminalROIC)}</b> of after-tax operating earnings.</div>${note('risk','Explain risk & competitive durability')}`;
 case 6:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">What belongs to common shareholders?</h2><p>Operating value becomes equity only after accounting for assets and other claims.</p></div>${claimsPanel()}${field('otherAssets','Other nonoperating assets','Only assets excluded from operating cash flows. Amounts in source-currency millions.',1,'m',0,100000,100)}${field('otherClaims','Other claims on equity',claimsDefinition(snapshot)?'Only claims not already included in the explicit model above. Count every claim once.':'Additional debt, minority/preferred interests, awards or obligations, counted once.',1,'m',0,100000,100)}${table('Captured source bridge',['Source bridge item',`${esc(snapshot.currency)} millions`],[[company.ticker==='GOOG'?'Captured cash + current marketables (includes equity)':'Captured cash & mapped securities',num(snapshot.cash)],['Mapped debt',num(snapshot.debt)],[claimsDefinition(snapshot)?'Captured cover-date shares (bridge uses dated basis above)':'Common shares',num(snapshot.shares,2)]])}<p class="micro">${esc(claimsDefinition(snapshot)&&company.ticker==='GOOG'?'The capture includes current marketable equity; the source-specific bridge above supplies the corrected definition.':raw.cashDefinition||'Cash restrictions require judgment.')} ${esc(raw.debtDefinition||'Review mapped debt and leases.')} ${esc(snapshot.shareBasis)}; dated ${esc(snapshot.coverShareDate||'unverified')}.</p><details><summary>Open accounting questions</summary><ul>${[...new Set([...(raw.reviewRequired||[]),...(raw.valuationBlockers||[])])].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Zero extra claims is an illustrative assumption. It is not evidence that no claims exist.</p></details>${note('claims','Explain your claims treatment')}`;
 case 7:return `<div class="editor-intro"><h2 id="guided-step-title" tabindex="-1">Follow every dollar.</h2><p>Cash-flow arithmetic and scenarios for the current assumptions.</p></div><button class="quiet" type="button" id="open-forecast-tables">Open full-width tables</button>${note('challenge','What new evidence would change your mind?')}<button id="freeze-current" class="primary">Export this valuation ↓</button><p id="freeze-status" class="micro" role="status"></p><details><summary>Method & limitations</summary><p>Original educational synthesis of Aswath Damodaran’s public framework. No affiliation or endorsement. Conditional values are not target prices, investment advice or calibrated probabilities.</p><a href="https://pages.stern.nyu.edu/~adamodar/New_Home_Page/webcastvalonline.htm" target="_blank" rel="noopener">Official valuation class ↗</a></details>`;
}}
