  --chart-one: #2343c4; --chart-two: #2b2f36;
  --history-mark: #c9cfd9; --approved-history: #c9cfd9;
  --history-mark-strong: #77808f; --approved-history-dark: #77808f;
  --stage: #f3f4f1; --stage-text: #14181e; --signal: #2343c4;
  --hero: #f3f4f1; --hero-text: #14181e; --hero-muted: #59606a;
  --warning: #85570b; --warning-bg: #f8eed8;
  --error: #ae2a20; --error-bg: #fae4e0;
  --focus: #2343c4; --secondary: #77808f;
  --sk-panel: #2343c4;
  --sk-header-bg: color-mix(in srgb, #f3f4f1 88%, transparent);
  --sk-primary-hover: #14181e; --sk-primary-hover-text: #ffffff;
}

