:root[data-skin="report"][data-theme="ocean"] {
  color-scheme: light;
  --paper: #eff2ee; --surface: #ffffff; --ink: #121a16; --muted: #55625a;
  --accent: #1e5b45; --on-accent: #ffffff; --soft: #e3ebe5; --line: #d7dfd9; --control: #9fb0a5;
