/* =====================================================================
   Annual Report · UX layer (report-ux.js)
   ===================================================================== */
:root[data-skin="report"] {
  /* Page and section changes rise in instead of blinking. */
  & .sk-route-enter { animation: rx-route 460ms cubic-bezier(.16, 1, .3, 1) both !important; }

  /* ---------- choice pills ---------- */
  & body select.rx-choice-host {
    position: absolute !important; width: 1px !important; height: 1px !important; min-height: 0 !important;
    padding: 0 !important; margin: 0 !important; border: 0 !important; opacity: 0 !important;
    pointer-events: none !important; clip-path: inset(50%) !important; overflow: hidden !important;
  }
  & body .rx-choice {
    position: relative; isolation: isolate; display: inline-flex; flex-wrap: wrap; gap: 2px; padding: 3px;
    border-radius: 12px; background: color-mix(in srgb, var(--ink) 6%, transparent);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 5%, transparent);
    max-width: 100%; vertical-align: middle; margin: 4px 0 2px;
  }
  & body .rx-choice > button {
    all: unset; box-sizing: border-box; position: relative; z-index: 1; cursor: pointer;
    padding: 8px 14px; border-radius: 9px; min-height: 36px; display: inline-flex; align-items: center;
    font: 550 13.5px/1.2 var(--sk-ui); letter-spacing: -.005em; color: var(--muted); text-align: center;
    transition: color 200ms;
  }
  & body .rx-choice > button:hover:not(:disabled) { color: var(--ink); }
  & body .rx-choice > button[aria-checked="true"] { color: var(--ink); }
  & body .rx-choice > button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
  & body .rx-choice > button:disabled { cursor: default; opacity: .45; }
  & body .rx-choice > button:active:not(:disabled) { scale: .97; }
  & body .rx-choice-ind {
    position: absolute; left: 0; top: 0; z-index: 0; border-radius: 9px; pointer-events: none;
    background: var(--surface); box-shadow: 0 1px 2px rgb(0 0 0 / .08), 0 4px 14px -6px rgb(0 0 0 / .18), inset 0 0 0 1px color-mix(in srgb, var(--ink) 6%, transparent);
    transition: transform 420ms cubic-bezier(.16, 1, .3, 1), width 420ms cubic-bezier(.16, 1, .3, 1), height 420ms cubic-bezier(.16, 1, .3, 1), opacity 200ms;
  }
  & body .rx-choice.is-disabled { opacity: .55; }
  /* A pill group's holder takes its row, so the group knows its real room. */
  & body :has(> .rx-choice) { min-width: 0; flex: 1 1 100%; max-width: 100%; align-self: stretch; justify-self: stretch; }
  & body .rx-choice.rx-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); width: 100%; }
  & body .rx-choice.rx-two > button { justify-content: center; }
  & body .rx-choice.rx-stacked { display: flex; flex-direction: column; width: 100%; }
  & body .rx-choice.rx-stacked > button { justify-content: flex-start; text-align: left; padding-inline: 14px; }
  /* A label that wraps its select keeps the caption above the pills. */
  & body label:has(> .rx-choice) { display: flex !important; flex-direction: column; align-items: flex-start; gap: 6px; }

  /* ---------- growth charts: one row, every year ---------- */
  & body .approved-growth-bars.annual-revenue-growth-bars,
  & body .approved-growth-bars {
    grid-template-columns: none !important; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr);
    column-gap: 6px !important; row-gap: 0 !important;
  }
  & body .approved-growth-bars .approved-growth-year { white-space: normal; text-align: center; line-height: 1.15; font-size: 11px !important; }
  & body .approved-growth-bars .approved-growth-bar { transform-origin: bottom; }
  & body .approved-growth-bars.rx-dense > :nth-child(even) :is(.approved-growth-year, .approved-growth-value) { visibility: hidden; }
  & body .approved-growth-bars.rx-dense > :is(:hover, :focus-visible) :is(.approved-growth-year, .approved-growth-value) { visibility: visible; }
  & body .approved-growth-bars > .approved-growth-column { min-width: 0; transition: opacity 200ms; }
  & body .approved-growth-bars:has(> .approved-growth-column:hover) > .approved-growth-column:not(:hover) { opacity: .55; }
  @media (max-width: 600px) {
    & body .approved-growth-bars { column-gap: 3px !important; }
    & body .approved-growth-bars .approved-growth-value { font-size: 9.5px !important; letter-spacing: -.02em; }
    & body .approved-growth-bars .approved-growth-year { font-size: 9.5px !important; }
    & body .approved-growth-bars:not(.rx-dense) > :nth-child(even) .approved-growth-value { visibility: hidden; }
  }
}
@keyframes rx-route {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }

}

